// SpecBoard がプロジェクト「データモデルの見本」から作ったファイルです。書き換えはプロジェクトで
/** 資料の種別 */
export type ItemKind = "book" | "magazine" | "disc";

/** ジャンル */
export type ItemGenre = "novel" | "essay" | "poetry" | "history" | "science" | "art" | "music" | "travel" | "cooking" | "children" | "comics" | "reference" | "language" | "sports";

/** 棚の大きさ */
export type ShelfSize = "small" | "medium" | "large" | "oversize";

/** 記録の対象の種別 */
export type LogTarget = "library" | "branch" | "item" | "member" | "loan";

/** 図書館 — 分館をまとめる単位。資料の貸し借りは図書館をまたげない。 */
export interface Library {
  /** 主キー */
  id: string;
  /** 館の名前 */
  name: string;
  /** 名前から作る — 一意 */
  slug: string;
  description?: string;
  openedAt: string;
  /** 変わるたびに書き直す */
  updatedAt: string;
  /** 分館 */
  branches?: Branch[];
}

/** 地図での位置 — Branch.mapPosition の入れ子スキーマ */
export interface BranchMapPosition {
  posX?: number;
  posY?: number;
  /** 手で置いた。自動の配置で動かさない */
  pinned?: boolean;
}

/** 分館 — 図書館の中のひとつの館。得意な資料の種別を一つ持つ。 */
export interface Branch {
  /** 主キー */
  id: string;
  library: Library;
  /** 図書館の中で一意。館の札の名前になる */
  name: string;
  /** 表示名 */
  label?: string;
  focus: ItemKind;
  description?: string;
  /** 地図での位置 — 案内図の表示のためだけに持ち、変更の記録に残さない */
  mapPosition?: BranchMapPosition;
  sortOrder: number;
  /** 資料 */
  items?: Item[];
}

/** 貸出の条件 — Item.loanTerms の入れ子スキーマ */
export interface ItemLoanTerms {
  isReference?: boolean;
  isRenewable?: boolean;
  isReservable?: boolean;
  isOversize?: boolean;
}

/** 資料 — 分館の持ち物。parent でまとめ物（全集・セット）の中の一冊を表し、入れ子の深さに限りはない。 */
export interface Item {
  /** 主キー */
  id: string;
  /** 入れ子の深さによらず、置いてある館を指す */
  branch: Branch;
  /** まとめ物 — null なら単独の資料。全集の一冊はこれで表す */
  parent?: Item;
  /** 同じ館で一意 */
  title: string;
  /** 表示名 */
  label?: string;
  genre: ItemGenre;
  /** 返す館 — ほかの館から借りたときだけ持つ */
  homeBranch?: Branch;
  size?: ShelfSize;
  /** 貸出の条件 */
  loanTerms?: ItemLoanTerms;
  /** 備考 */
  note?: string;
  sortOrder: number;
}

/** 利用者 — 分館で登録した利用者。 */
export interface Member {
  /** 主キー */
  id: string;
  branch: Branch;
  cardNumber: string;
  name?: string;
  sortOrder: number;
}

/** 記録の対象 — ActivityLog.target の入れ子スキーマ */
export interface ActivityLogTarget {
  type: LogTarget;
  id?: string;
}

/** 活動の記録 — 貸し出しや登録のたびに一行ずつ足す記録。書き換えず、消さない。 */
export interface ActivityLog {
  /** 主キー */
  id: string;
  library: Library;
  at: string;
  /** item.lend / member.register など */
  kind: string;
  /** 記録の対象 */
  target?: ActivityLogTarget;
  /** 画面にそのまま出す一行 */
  summary: string;
  /** そのときの中身の写し */
  payload?: unknown;
}

