// SpecBoard がプロジェクト「データモデルの見本」から作ったファイルです。書き換えはプロジェクトで
import { z } from "zod";

// オブジェクトは z.strictObject です。未知のフィールドは strip されず拒否されます
// （JSON Schema 出力の additionalProperties: false と一致させています）。

// 循環参照・相互参照は Zod 4 のゲッター記法で表現しています。
// 型推論はそのまま効くので、追加の型注釈は要りません。

/** 資料の種別 */
export const ItemKind = z.enum(["book", "magazine", "disc"]);
export type ItemKind = z.infer<typeof ItemKind>;

/** ジャンル */
export const ItemGenre = z.enum(["novel", "essay", "poetry", "history", "science", "art", "music", "travel", "cooking", "children", "comics", "reference", "language", "sports"]);
export type ItemGenre = z.infer<typeof ItemGenre>;

/** 棚の大きさ */
export const ShelfSize = z.enum(["small", "medium", "large", "oversize"]);
export type ShelfSize = z.infer<typeof ShelfSize>;

/** 記録の対象の種別 */
export const LogTarget = z.enum(["library", "branch", "item", "member", "loan"]);
export type LogTarget = z.infer<typeof LogTarget>;

/** 資料 — 分館の持ち物。parent でまとめ物（全集・セット）の中の一冊を表し、入れ子の深さに限りはない。 */
export const Item = z.strictObject({
  // 主キー
  id: z.uuid(),
  // 入れ子の深さによらず、置いてある館を指す
  get branch() { return Branch; },
  // まとめ物
  // null なら単独の資料。全集の一冊はこれで表す
  get parent() { return Item.optional(); },
  // 同じ館で一意
  title: z.string(),
  // 表示名
  label: z.string().optional(),
  genre: ItemGenre,
  // 返す館
  // ほかの館から借りたときだけ持つ
  get homeBranch() { return Branch.optional(); },
  size: ShelfSize.optional(),
  // 貸出の条件
  loanTerms: z.strictObject({
    isReference: z.boolean().optional(),
    isRenewable: z.boolean().optional(),
    isReservable: z.boolean().optional(),
    isOversize: z.boolean().optional(),
  }).optional(),
  // 備考
  note: z.string().optional(),
  sortOrder: z.int(),
});
export type Item = z.infer<typeof Item>;

/** 分館 — 図書館の中のひとつの館。得意な資料の種別を一つ持つ。 */
export const Branch = z.strictObject({
  // 主キー
  id: z.uuid(),
  get library() { return Library; },
  // 図書館の中で一意。館の札の名前になる
  name: z.string(),
  // 表示名
  label: z.string().optional(),
  focus: ItemKind,
  description: z.string().optional(),
  // 地図での位置
  // 案内図の表示のためだけに持ち、変更の記録に残さない
  mapPosition: z.strictObject({
    posX: z.number().optional(),
    posY: z.number().optional(),
    // 手で置いた。自動の配置で動かさない
    pinned: z.boolean().optional(),
  }).optional(),
  sortOrder: z.int(),
  // 資料
  items: z.array(Item).optional(),
});
export type Branch = z.infer<typeof Branch>;

/** 図書館 — 分館をまとめる単位。資料の貸し借りは図書館をまたげない。 */
export const Library = z.strictObject({
  // 主キー
  id: z.uuid(),
  // 館の名前
  name: z.string(),
  // 名前から作る
  // 一意
  slug: z.string(),
  description: z.string().optional(),
  openedAt: z.iso.datetime(),
  // 変わるたびに書き直す
  updatedAt: z.iso.datetime(),
  // 分館
  branches: z.array(Branch).optional(),
});
export type Library = z.infer<typeof Library>;

/** 利用者 — 分館で登録した利用者。 */
export const Member = z.strictObject({
  // 主キー
  id: z.uuid(),
  branch: Branch,
  cardNumber: z.string(),
  name: z.string().optional(),
  sortOrder: z.int(),
});
export type Member = z.infer<typeof Member>;

/** 活動の記録 — 貸し出しや登録のたびに一行ずつ足す記録。書き換えず、消さない。 */
export const ActivityLog = z.strictObject({
  // 主キー
  id: z.uuid(),
  library: Library,
  at: z.iso.datetime(),
  // item.lend / member.register など
  kind: z.string(),
  // 記録の対象
  target: z.strictObject({
    type: LogTarget,
    id: z.uuid().optional(),
  }).optional(),
  // 画面にそのまま出す一行
  summary: z.string(),
  // そのときの中身の写し
  payload: z.unknown().optional(),
});
export type ActivityLog = z.infer<typeof ActivityLog>;
